head.b:skin:
/*
-----------------------------------------------------------------
Theme Name: Quickfever Modern Magazine Theme
Platform: Blogger / Blogspot (Layouts Version 3)
-----------------------------------------------------------------
*/

:root {
  --qf-primary: #e00613;
  --qf-primary-hover: #c0040f;
  --qf-header-bg: #000000;
  --qf-header-color: #ffffff;
  --qf-text-main: #111111;
  --qf-text-muted: #666666;
  --qf-text-light: #888888;
  --qf-bg-body: #ffffff;
  --qf-border: #e5e7eb;
  --qf-border-light: #f1f5f9;
  --qf-discover-bg: #eef3fc;
  --qf-discover-border: #dbe7f6;
  --qf-hero-bg: #fdd7d7;
  --qf-font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --qf-radius-sm: 4px;
  --qf-radius-md: 6px;
  --qf-radius-lg: 8px;
  --qf-container-width: 1240px;
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--qf-font-sans);
  background-color: var(--qf-bg-body);
  color: var(--qf-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.15s ease, opacity 0.15s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* -------------------------------------------------------------
   Header
   ------------------------------------------------------------- */
.qf-header {
  background-color: var(--qf-header-bg);
  color: var(--qf-header-color);
  height: 56px;
  position: relative;
  z-index: 900;
}

.qf-header-inner {
  max-width: var(--qf-container-width);
  height: 100%;
  margin: 0 auto;
  padding: 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.qf-header-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.qf-hamburger-btn {
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  margin-left: -6px;
}
.qf-hamburger-btn svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
}

.qf-logo {
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 1.2px;
  color: #ffffff;
  text-transform: uppercase;
  white-space: nowrap;
}

/* Desktop Navigation */
.qf-nav {
  display: flex;
  align-items: center;
  list-style: none;
  gap: 22px;
  margin-left: 20px;
}

.qf-nav > li {
  position: relative;
}

.qf-nav > li > a {
  color: #ffffff;
  font-size: 13.5px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 0;
  white-space: nowrap;
  opacity: 0.95;
}
.qf-nav > li > a:hover {
  opacity: 1;
}

.qf-dropdown-icon {
  width: 10px;
  height: 10px;
  fill: currentColor;
  transition: transform 0.2s ease;
}

.qf-nav > li:hover .qf-dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.qf-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  background: #111111;
  min-width: 180px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  border-radius: 4px;
  padding: 8px 0;
  list-style: none;
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition: all 0.2s ease;
  z-index: 100;
  border: 1px solid #222;
}
.qf-dropdown li a {
  display: block;
  padding: 8px 16px;
  font-size: 13px;
  color: #ddd;
  font-weight: 500;
}
.qf-dropdown li a:hover {
  background: #1a1a1a;
  color: #fff;
}

/* Header Right */
.qf-header-right {
  display: flex;
  align-items: center;
  gap: 14px;
}

.qf-search-btn {
  background: none;
  border: none;
  color: #ffffff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  opacity: 0.9;
  transition: opacity 0.2s;
}
.qf-search-btn:hover {
  opacity: 1;
}
.qf-search-btn svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.qf-btn-red {
  background-color: var(--qf-primary);
  color: #ffffff !important;
  font-size: 12.5px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  transition: background-color 0.15s ease;
}
.qf-btn-red:hover {
  background-color: var(--qf-primary-hover);
}

/* -------------------------------------------------------------
   Main Wrapper & Common Elements
   ------------------------------------------------------------- */
.qf-main-wrap {
  max-width: var(--qf-container-width);
  margin: 0 auto;
  padding: 24px 16px 60px;
}

.qf-section-title {
  font-size: 11px;
  font-weight: 800;
  color: var(--qf-text-muted);
  letter-spacing: 1.2px;
  text-transform: uppercase;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.qf-badge-red {
  color: var(--qf-primary);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  display: inline-block;
  margin-bottom: 4px;
}
.qf-badge-red::before {
  content: '> ';
  font-weight: 900;
}

/* -------------------------------------------------------------
   Homepage: APP DIRECTORY (Ranked 1 to 5 via CSS Counters)
   ------------------------------------------------------------- */
.qf-app-directory {
  margin-bottom: 40px;
}

.qf-rank-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  counter-reset: qf-rank;
}

.qf-rank-card {
  display: flex;
  flex-direction: column;
  counter-increment: qf-rank;
}

.qf-rank-thumb {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  background-color: #f1f3f5;
  border-radius: var(--qf-radius-sm);
  overflow: hidden;
  margin-bottom: 10px;
  border: 1px solid #ededed;
}
.qf-rank-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}
.qf-rank-card:hover .qf-rank-thumb img {
  transform: scale(1.03);
}

.qf-rank-info {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.qf-rank-num {
  font-size: 32px;
  font-weight: 900;
  line-height: 1;
  color: var(--qf-text-main);
  min-width: 20px;
  font-family: var(--qf-font-sans);
}
.qf-rank-num::before {
  content: counter(qf-rank);
}

.qf-rank-meta {
  flex: 1;
}

.qf-rank-title {
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--qf-text-main);
  margin-bottom: 4px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.qf-rank-title a:hover {
  color: var(--qf-primary);
}

.qf-rank-author {
  font-size: 11px;
  color: var(--qf-text-muted);
}
.qf-rank-author a {
  text-decoration: underline;
}

/* -------------------------------------------------------------
   Homepage: ARTICLES Grid
   ------------------------------------------------------------- */
.qf-articles-section {
  margin-top: 10px;
}

.qf-articles-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

/* Left Featured Article */
.qf-featured-left {
  display: flex;
  flex-direction: column;
}

.qf-featured-thumb {
  width: 100%;
  aspect-ratio: 16 / 10;
  background: #f1f3f5;
  border-radius: var(--qf-radius-sm);
  overflow: hidden;
  margin-bottom: 14px;
  border: 1px solid #ededed;
}
.qf-featured-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}
.qf-featured-left:hover .qf-featured-thumb img {
  transform: scale(1.02);
}

.qf-featured-title {
  font-size: 26px;
  font-weight: 800;
  line-height: 1.25;
  color: var(--qf-text-main);
  margin: 6px 0 10px;
}
.qf-featured-title a:hover {
  color: var(--qf-primary);
}

.qf-featured-snippet {
  font-size: 14px;
  color: var(--qf-text-muted);
  line-height: 1.55;
}

/* Right 2x2 Subgrid */
.qf-articles-subgrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px 24px;
}

.qf-sub-card {
  display: flex;
  flex-direction: column;
}

.qf-sub-thumb {
  width: 100%;
  aspect-ratio: 16 / 10;
  background: #f1f3f5;
  border-radius: var(--qf-radius-sm);
  overflow: hidden;
  margin-bottom: 10px;
  border: 1px solid #ededed;
}
.qf-sub-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}
.qf-sub-card:hover .qf-sub-thumb img {
  transform: scale(1.03);
}

.qf-sub-title {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--qf-text-main);
  margin: 4px 0 6px;
}
.qf-sub-title a:hover {
  color: var(--qf-primary);
}

.qf-sub-meta {
  font-size: 11px;
  color: var(--qf-text-muted);
}
.qf-sub-meta a {
  text-decoration: underline;
}

/* Additional posts stream */
.qf-more-posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
  padding-top: 32px;
  border-top: 1px solid var(--qf-border);
}

/* Pagination */
.qf-pagination {
  margin-top: 40px;
  display: flex;
  justify-content: center;
  gap: 12px;
}
.qf-pagination a {
  padding: 8px 18px;
  background: #ffffff;
  border: 1px solid var(--qf-border);
  font-size: 13px;
  font-weight: 600;
  border-radius: 4px;
}
.qf-pagination a:hover {
  background: var(--qf-primary);
  color: #fff;
  border-color: var(--qf-primary);
}

/* -------------------------------------------------------------
   Layout Structure: Content & Sidebar
   ------------------------------------------------------------- */
.qf-content-sidebar-wrap {
  width: 100%;
}

/* On Homepage / Multiple Items: Full Width, No Sidebar */
body.qf-is-home .qf-content-sidebar-wrap {
  display: block;
}
body.qf-is-home .qf-sidebar {
  display: none !important;
}

/* On Single Post / Page: 2-Column Grid Layout with Sidebar */
body.qf-is-single .qf-content-sidebar-wrap {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 48px;
  align-items: start;
}
body.qf-is-single .qf-sidebar {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* -------------------------------------------------------------
   Single Post Layout (Dia Browser style)
   ------------------------------------------------------------- */
.qf-post-main {
  min-width: 0;
}

.qf-post-header {
  margin-bottom: 24px;
}

.qf-single-title {
  font-size: 34px;
  font-weight: 800;
  line-height: 1.2;
  color: var(--qf-text-main);
  margin: 8px 0 12px;
  letter-spacing: -0.3px;
}

.qf-single-deck {
  font-size: 17px;
  line-height: 1.5;
  color: #3e3e3e;
  margin-bottom: 16px;
  font-weight: 400;
}

.qf-single-meta {
  font-size: 12.5px;
  color: var(--qf-text-muted);
  padding-bottom: 16px;
  border-bottom: 1px solid var(--qf-border);
}
.qf-single-meta a {
  text-decoration: underline;
  color: var(--qf-text-main);
  font-weight: 500;
}

/* Hero image with soft peach/pink container matching screenshot */
.qf-hero-box {
  background-color: var(--qf-hero-bg);
  border-radius: var(--qf-radius-sm);
  padding: 32px 24px;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 24px 0 32px;
}
.qf-hero-inner {
  background: #ffffff;
  border-radius: var(--qf-radius-sm);
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
  max-width: 100%;
}
.qf-hero-inner img {
  width: 100%;
  height: auto;
  display: block;
}

/* Post Body Content */
.qf-post-body {
  font-size: 16.5px;
  line-height: 1.75;
  color: #222222;
}
.qf-post-body p {
  margin-bottom: 20px;
}
.qf-post-body h2 {
  font-size: 24px;
  font-weight: 800;
  margin: 36px 0 16px;
  color: var(--qf-text-main);
  line-height: 1.3;
}
.qf-post-body h3 {
  font-size: 20px;
  font-weight: 700;
  margin: 28px 0 14px;
  color: var(--qf-text-main);
}
.qf-post-body ul, .qf-post-body ol {
  margin: 16px 0 24px 24px;
}
.qf-post-body li {
  margin-bottom: 8px;
}
.qf-post-body blockquote {
  border-left: 3px solid var(--qf-primary);
  padding: 12px 20px;
  margin: 24px 0;
  background: #fafafa;
  font-style: italic;
  color: #444;
}
.qf-post-body pre {
  background: #111827;
  color: #f3f4f6;
  padding: 16px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 13.5px;
  margin: 24px 0;
}

/* -------------------------------------------------------------
   Sidebar Widgets
   ------------------------------------------------------------- */
.qf-widget-discover {
  background: #ffffff;
  border: 1px solid var(--qf-discover-border);
  border-radius: var(--qf-radius-sm);
  overflow: hidden;
}

.qf-discover-head {
  background-color: var(--qf-discover-bg);
  padding: 12px 18px;
  font-size: 14.5px;
  font-weight: 700;
  color: #1e293b;
  border-bottom: 1px solid var(--qf-discover-border);
}

.qf-discover-list {
  list-style: none;
}

.qf-discover-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  font-size: 13.5px;
  font-weight: 500;
  color: #334155;
  border-bottom: 1px solid #f1f5f9;
  transition: all 0.15s ease;
}
.qf-discover-item:last-child {
  border-bottom: none;
}
.qf-discover-item:hover {
  background-color: #f8fafc;
  color: var(--qf-primary);
  padding-left: 21px;
}
.qf-chevron-icon {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: #94a3b8;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 0.15s, transform 0.15s;
}
.qf-discover-item:hover .qf-chevron-icon {
  stroke: var(--qf-primary);
  transform: translateX(2px);
}

/* Top News Widget */
.qf-widget-topnews {
  margin-top: 8px;
}
.qf-widget-title {
  font-size: 13.5px;
  font-weight: 800;
  color: var(--qf-text-main);
  margin-bottom: 14px;
}
.qf-news-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.qf-news-item {
  display: flex;
  gap: 12px;
  align-items: center;
}
.qf-news-thumb {
  width: 70px;
  height: 50px;
  flex-shrink: 0;
  border-radius: 3px;
  overflow: hidden;
  background: #f1f3f5;
}
.qf-news-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.qf-news-title {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  color: #111;
}
.qf-news-title a:hover {
  color: var(--qf-primary);
}

/* -------------------------------------------------------------
   Footer
   ------------------------------------------------------------- */
.qf-footer {
  background: #111111;
  color: #999999;
  font-size: 13px;
  padding: 40px 16px 24px;
  margin-top: 60px;
  border-top: 1px solid #222;
}
.qf-footer-inner {
  max-width: var(--qf-container-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  text-align: center;
}
.qf-footer-logo {
  font-size: 20px;
  font-weight: 900;
  color: #ffffff;
  letter-spacing: 1px;
}
.qf-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  list-style: none;
}
.qf-footer-links a {
  color: #bbb;
}
.qf-footer-links a:hover {
  color: #fff;
}
.qf-footer-copy {
  color: #666;
  font-size: 12px;
}

/* -------------------------------------------------------------
   Mobile Drawer & Search Modal
   ------------------------------------------------------------- */
.qf-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 1100;
}
.qf-drawer-overlay.active {
  opacity: 1;
  visibility: visible;
}

.qf-drawer {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 290px;
  background: #111111;
  color: #fff;
  transform: translateX(-100%);
  transition: transform 0.3s ease;
  z-index: 1200;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  box-shadow: 4px 0 24px rgba(0,0,0,0.4);
}
.qf-drawer.active {
  transform: translateX(0);
}

.qf-drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid #222;
}
.qf-drawer-close {
  background: none;
  border: none;
  color: #aaa;
  cursor: pointer;
  font-size: 20px;
  padding: 4px;
}
.qf-drawer-close:hover {
  color: #fff;
}

.qf-drawer-nav {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.qf-drawer-nav a {
  font-size: 15px;
  font-weight: 600;
  color: #eee;
  display: block;
  padding: 8px 0;
}
.qf-drawer-nav a:hover {
  color: var(--qf-primary);
}

/* Search Modal */
.qf-search-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 100px;
  z-index: 1300;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
}
.qf-search-modal.active {
  opacity: 1;
  visibility: visible;
}
.qf-search-box {
  background: #ffffff;
  width: 100%;
  max-width: 600px;
  border-radius: 8px;
  padding: 20px;
  box-shadow: 0 16px 40px rgba(0,0,0,0.3);
}
.qf-search-input-wrap {
  display: flex;
  gap: 10px;
}
.qf-search-input {
  flex: 1;
  padding: 12px 16px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 15px;
  outline: none;
}
.qf-search-input:focus {
  border-color: var(--qf-primary);
}

/* -------------------------------------------------------------
   Responsive Breakpoints
   ------------------------------------------------------------- */
@media (max-width: 1080px) {
  .qf-nav {
    gap: 14px;
    margin-left: 14px;
  }
  .qf-nav > li > a {
    font-size: 12.5px;
  }
  .qf-rank-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 992px) {
  body.qf-is-single .qf-content-sidebar-wrap {
    grid-template-columns: 1fr;
    gap: 36px;
  }
}

@media (max-width: 860px) {
  .qf-nav {
    display: none;
  }
  .qf-articles-grid {
    grid-template-columns: 1fr;
  }
  .qf-rank-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .qf-more-posts-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 580px) {
  .qf-rank-grid {
    grid-template-columns: 1fr;
  }
  .qf-articles-subgrid {
    grid-template-columns: 1fr;
  }
  .qf-more-posts-grid {
    grid-template-columns: 1fr;
  }
  .qf-single-title {
    font-size: 26px;
  }
  .qf-single-deck {
    font-size: 15px;
  }
}
